#include <errno.h>
#include <ctype.h>
typedef struct { char name[128]; size_t address; } JVM_vw_label;
static int JVM_vw_token(const char **source, char *out, size_t capacity) {
  const char *p=*source; size_t count=0;
  for(;;) {
    while(*p && isspace((unsigned char)*p)) ++p;
    if(*p!='#') break;
    while(*p && *p!='\n') ++p;
  }
  if(!*p) { *source=p; return 0; }
  while(*p && !isspace((unsigned char)*p) && *p!='#') {
    if(count+1>=capacity) return -1;
    out[count++]=*p++;
  }
  out[count]=0; *source=p; return 1;
}
static const JVM_metadata *JVM_vw_mnemonic(const char *name) {
  if(strcmp(name,"DUP")==0) return JVM_lookup(0u);
  if(strcmp(name,"GOTO")==0) return JVM_lookup(1u);
  if(strcmp(name,"HALT")==0) return JVM_lookup(2u);
  if(strcmp(name,"IADD")==0) return JVM_lookup(3u);
  if(strcmp(name,"IAND")==0) return JVM_lookup(4u);
  if(strcmp(name,"ICONST")==0) return JVM_lookup(5u);
  if(strcmp(name,"IDIV")==0) return JVM_lookup(6u);
  if(strcmp(name,"IFEQ")==0) return JVM_lookup(7u);
  if(strcmp(name,"IF_ICMPLT")==0) return JVM_lookup(8u);
  if(strcmp(name,"IINC")==0) return JVM_lookup(9u);
  if(strcmp(name,"ILOAD")==0) return JVM_lookup(10u);
  if(strcmp(name,"IMUL")==0) return JVM_lookup(11u);
  if(strcmp(name,"INEG")==0) return JVM_lookup(12u);
  if(strcmp(name,"INVOKESTATIC")==0) return JVM_lookup(13u);
  if(strcmp(name,"INVOKESTATIC1")==0) return JVM_lookup(14u);
  if(strcmp(name,"IOR")==0) return JVM_lookup(15u);
  if(strcmp(name,"IREM")==0) return JVM_lookup(16u);
  if(strcmp(name,"IRETURN")==0) return JVM_lookup(17u);
  if(strcmp(name,"ISTORE")==0) return JVM_lookup(18u);
  if(strcmp(name,"ISUB")==0) return JVM_lookup(19u);
  if(strcmp(name,"IXOR")==0) return JVM_lookup(20u);
  if(strcmp(name,"POP")==0) return JVM_lookup(21u);
  if(strcmp(name,"PRINT")==0) return JVM_lookup(22u);
  if(strcmp(name,"RETURN")==0) return JVM_lookup(23u);
  if(strcmp(name,"SWAP")==0) return JVM_lookup(24u);
  return NULL;
}
/* Caller-owned output, transactional validation, labels are instruction indices. */
int JVM_compile(const char *source, JVM_tape *out) {
  JVM_vw_label labels[256]; size_t label_count=0, count=0, total=0, pass;
  char token[128];
  if(!source || !out || out->size>out->capacity || (out->capacity && !out->data)) return -1;
  for(pass=0;pass<3;++pass) {
    const char *cursor=source; int got; count=0;
    while((got=JVM_vw_token(&cursor,token,sizeof(token)))>0) {
      size_t len=strlen(token), j; const JVM_metadata *info;
      if(len && token[len-1]==':') {
        token[len-1]=0; if(!token[0]) return -4;
        if(pass==0) {
          if(label_count==256) return -3;
          for(j=0;j<label_count;++j) if(strcmp(labels[j].name,token)==0) return -4;
          strcpy(labels[label_count].name,token); labels[label_count++].address=count;
        }
        continue;
      }
      info=JVM_vw_mnemonic(token); if(!info) return -4;
      if(count>=out->capacity) return -3;
      if(pass==2) {memset(&out->data[count],0,sizeof(out->data[count]));
        out->data[count].opcode=info->opcode; out->data[count].operand_count=info->operands;}
      for(j=0;j<info->operands;++j) {
        JVM_cell value=0; char *end; intmax_t parsed;
        if(JVM_vw_token(&cursor,token,sizeof(token))!=1) return -4;
        if(token[0]=='&') {
          size_t k;
          if(pass) {for(k=0;k<label_count && strcmp(labels[k].name,token+1)!=0;++k) {} if(k==label_count) return -4; value=(JVM_cell)labels[k].address;}
        } else {
          errno=0; parsed=strtoimax(token,&end,0);
          if(errno || *end || end==token || (intmax_t)(JVM_cell)parsed!=parsed) return -4;
          value=(JVM_cell)parsed;
        }
        if(pass && JVM_vw_label_operand(info->opcode,j) && (uintmax_t)value>=total) return -4;
        if(pass==2) out->data[count].operands[j]=value;
      }
      ++count;
    }
    if(got<0) return -4;
    if(pass==0) total=count;
  }
  out->size=count; return 0;
}

/* .tape */
int JVM_tape_validate(const JVM_tape *tape) {
  size_t i;
  if(!tape || tape->size>tape->capacity || (tape->size && !tape->data)) return -1;
  for(i=0;i<tape->size;++i) if(JVM_vw_validate_instruction(&tape->data[i],tape->size)) return -4;
  return 0;
}

/* .frame */
int JVM_call(JVM_vm *vm, JVM_cell target) {
  JVM_activation *frame;
  if(!vm || vm->vw_error) return vm ? vm->vw_error : -1;
  if((uintmax_t)target>=vm->vw_code_size) { JVM_vw_fail(vm,-4); return -4; }
  if(vm->vw_frame_count>=sizeof(vm->vw_frames)/sizeof(vm->vw_frames[0])) { JVM_vw_fail(vm,-3); return -3; }
  frame=&vm->vw_frames[vm->vw_frame_count++]; memset(frame,0,sizeof(*frame));
  frame->return_address=vm->vw_pc; frame->stack_base=vm->vw_sp; vm->vw_pc=(size_t)target; return 0;
}
int JVM_ret(JVM_vm *vm) {
  if(!vm || vm->vw_error) return vm ? vm->vw_error : -1;
  if(!vm->vw_frame_count) { JVM_vw_fail(vm,-2); return -2; }
  vm->vw_pc=vm->vw_frames[--vm->vw_frame_count].return_address; return 0;
}
